<script setup lang="ts">
import { Head, Link, router, useForm, usePage } from '@inertiajs/vue3';
import { computed } from 'vue';
import FieldError from '../../../components/FieldError.vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';
import type { PageProps } from '../../../types';

interface Supplier { id: string; name: string; code: string; contact_name: string | null; email: string | null; phone: string | null; website: string | null; notes: string | null; status: string }
interface Variant { id: string; product_name: string; name: string | null; sku: string }
interface SupplierProduct { id: string; product_variant_id: string; product_name: string; variant_name: string | null; sku: string; supplier_sku: string | null; unit_cost: string; currency: string; minimum_order_quantity: number; order_multiple: number | null; lead_time_days: number | null; is_preferred: boolean; notes: string | null; status: string }

const props = defineProps<{ supplier: Supplier; products: SupplierProduct[]; variants: Variant[]; statuses: string[] }>();
const page = usePage<PageProps>();
const permissions = computed(() => page.props.currentTenantMembership?.permissions ?? []);
const canUpdate = computed(() => permissions.value.includes('suppliers.update'));
const canArchive = computed(() => permissions.value.includes('suppliers.archive'));
const supplierForm = useForm({ name: props.supplier.name, code: props.supplier.code, contact_name: props.supplier.contact_name ?? '', email: props.supplier.email ?? '', phone: props.supplier.phone ?? '', website: props.supplier.website ?? '', notes: props.supplier.notes ?? '', status: props.supplier.status });
const productForm = useForm({ product_variant_id: '', supplier_sku: '', unit_cost: '', currency: page.props.currentStore?.currency ?? '', minimum_order_quantity: 1, order_multiple: null as number | null, lead_time_days: null as number | null, is_preferred: false, notes: '' });
const productForms = props.products.map((product) => ({ id: product.id, form: useForm({ supplier_sku: product.supplier_sku ?? '', unit_cost: product.unit_cost, currency: product.currency, minimum_order_quantity: product.minimum_order_quantity, order_multiple: product.order_multiple, lead_time_days: product.lead_time_days, is_preferred: product.is_preferred, notes: product.notes ?? '', status: product.status }) }));
const saveSupplier = () => router.patch(`/admin/suppliers/${props.supplier.id}`, supplierForm.data(), { preserveScroll: true, onError: (errors) => supplierForm.setError(errors) });
const addProduct = () => productForm.post(`/admin/suppliers/${props.supplier.id}/products`, { preserveScroll: true, onSuccess: () => productForm.reset() });
const saveProduct = (entry: (typeof productForms)[number]) => router.patch(`/admin/supplier-products/${entry.id}`, entry.form.data(), { preserveScroll: true, onError: (errors) => entry.form.setError(errors) });
const archiveProduct = (product: SupplierProduct) => { if (window.confirm(`Archive ${product.sku} from this supplier?`)) router.post(`/admin/supplier-products/${product.id}/archive`, {}, { preserveScroll: true }); };
const archiveSupplier = () => { if (window.confirm(`Archive ${props.supplier.name}?`)) router.post(`/admin/suppliers/${props.supplier.id}/archive`); };
</script>

<template>
    <Head :title="supplier.name" />
    <AdminLayout><section><div class="flex flex-wrap items-end justify-between gap-5"><div><p class="font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">Supplier record / {{ supplier.status }}</p><h1 class="mt-4 text-4xl font-semibold tracking-[-0.04em] sm:text-6xl">{{ supplier.name }}.</h1></div><div class="flex flex-wrap gap-4"><button v-if="canArchive && supplier.status !== 'ARCHIVED'" class="px-4 py-3 text-sm font-semibold text-red-800" @click="archiveSupplier">Archive supplier</button><Link href="/admin/suppliers" class="border border-[#17211b] px-4 py-3 text-sm font-semibold">Back to suppliers</Link></div></div>
        <p v-if="page.props.status" class="mt-6 border border-emerald-800/20 bg-emerald-50 px-4 py-3 text-sm text-emerald-900">{{ page.props.status }}</p>
        <form class="mt-8 grid gap-5 border border-[#17211b]/15 bg-[#f8f5ed] p-6 sm:grid-cols-2 sm:p-8" @submit.prevent="saveSupplier"><div><label class="mb-2 block font-semibold">Name</label><input v-model="supplierForm.name" :disabled="!canUpdate" required class="w-full border bg-white px-4 py-3 disabled:opacity-60" /><FieldError :message="supplierForm.errors.name" /></div><div><label class="mb-2 block font-semibold">Code</label><input v-model="supplierForm.code" :disabled="!canUpdate" required class="w-full border bg-white px-4 py-3 font-mono disabled:opacity-60" /><FieldError :message="supplierForm.errors.code" /></div><div><label class="mb-2 block font-semibold">Contact name</label><input v-model="supplierForm.contact_name" :disabled="!canUpdate" class="w-full border bg-white px-4 py-3 disabled:opacity-60" /><FieldError :message="supplierForm.errors.contact_name" /></div><div><label class="mb-2 block font-semibold">Email</label><input v-model="supplierForm.email" :disabled="!canUpdate" type="email" class="w-full border bg-white px-4 py-3 disabled:opacity-60" /><FieldError :message="supplierForm.errors.email" /></div><div><label class="mb-2 block font-semibold">Phone</label><input v-model="supplierForm.phone" :disabled="!canUpdate" class="w-full border bg-white px-4 py-3 disabled:opacity-60" /><FieldError :message="supplierForm.errors.phone" /></div><div><label class="mb-2 block font-semibold">Website</label><input v-model="supplierForm.website" :disabled="!canUpdate" type="url" class="w-full border bg-white px-4 py-3 disabled:opacity-60" /><FieldError :message="supplierForm.errors.website" /></div><div><label class="mb-2 block font-semibold">Status</label><select v-model="supplierForm.status" :disabled="!canUpdate" class="w-full border bg-white px-4 py-3 disabled:opacity-60"><option v-for="value in statuses" :key="value" :value="value">{{ value }}</option></select><FieldError :message="supplierForm.errors.status" /></div><div class="sm:col-span-2"><label class="mb-2 block font-semibold">Internal notes</label><textarea v-model="supplierForm.notes" :disabled="!canUpdate" rows="4" maxlength="10000" class="w-full border bg-white px-4 py-3 disabled:opacity-60" /><FieldError :message="supplierForm.errors.notes" /></div><button v-if="canUpdate" class="w-fit bg-[#17211b] px-5 py-3 text-sm font-semibold text-white">Save supplier</button></form>

        <div class="mt-14"><p class="font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">Supplier catalog</p><h2 class="mt-3 text-3xl font-semibold">Products</h2></div>
        <div class="mt-6 grid gap-4"><form v-for="(entry, index) in productForms" :key="entry.id" class="grid gap-4 border border-[#17211b]/15 bg-white p-5 md:grid-cols-4" @submit.prevent="saveProduct(entry)"><div class="md:col-span-4"><p class="font-semibold">{{ products[index].product_name }}</p><p class="text-xs text-[#637067]">{{ products[index].variant_name ?? 'Default variant' }} / {{ products[index].sku }} / {{ products[index].status }}</p></div><label class="text-sm font-semibold">Supplier SKU<input v-model="entry.form.supplier_sku" :disabled="!canUpdate" class="mt-2 w-full border px-3 py-2 font-mono font-normal disabled:opacity-60" /></label><label class="text-sm font-semibold">Unit cost<input v-model="entry.form.unit_cost" :disabled="!canUpdate" inputmode="decimal" class="mt-2 w-full border px-3 py-2 font-mono font-normal disabled:opacity-60" /></label><label class="text-sm font-semibold">Currency<input v-model="entry.form.currency" :disabled="!canUpdate" maxlength="3" class="mt-2 w-full border px-3 py-2 font-mono font-normal uppercase disabled:opacity-60" /></label><label class="text-sm font-semibold">Status<select v-model="entry.form.status" :disabled="!canUpdate || products[index].status === 'ARCHIVED'" class="mt-2 w-full border px-3 py-2 font-normal disabled:opacity-60"><option value="ACTIVE">ACTIVE</option><option value="INACTIVE">INACTIVE</option><option v-if="products[index].status === 'ARCHIVED'" value="ARCHIVED">ARCHIVED</option></select></label><label class="text-sm font-semibold">Minimum order<input v-model.number="entry.form.minimum_order_quantity" :disabled="!canUpdate" type="number" min="1" class="mt-2 w-full border px-3 py-2 font-mono font-normal disabled:opacity-60" /></label><label class="text-sm font-semibold">Order multiple<input v-model.number="entry.form.order_multiple" :disabled="!canUpdate" type="number" min="1" class="mt-2 w-full border px-3 py-2 font-mono font-normal disabled:opacity-60" /></label><label class="text-sm font-semibold">Lead days<input v-model.number="entry.form.lead_time_days" :disabled="!canUpdate" type="number" min="0" class="mt-2 w-full border px-3 py-2 font-mono font-normal disabled:opacity-60" /></label><label class="flex items-center gap-2 pb-2 text-sm font-semibold"><input v-model="entry.form.is_preferred" :disabled="!canUpdate" type="checkbox" /> Preferred supplier product</label><label class="text-sm font-semibold md:col-span-4">Notes<textarea v-model="entry.form.notes" :disabled="!canUpdate" rows="2" maxlength="10000" class="mt-2 w-full border px-3 py-2 font-normal disabled:opacity-60" /></label><div class="flex gap-4 md:col-span-4"><button v-if="canUpdate && products[index].status !== 'ARCHIVED'" class="font-semibold text-emerald-800">Save product</button><button v-if="canArchive && products[index].status !== 'ARCHIVED'" type="button" class="font-semibold text-red-800" @click="archiveProduct(products[index])">Archive product</button></div><FieldError class="md:col-span-4" :message="entry.form.errors.supplier_sku ?? entry.form.errors.unit_cost ?? entry.form.errors.currency ?? entry.form.errors.minimum_order_quantity ?? entry.form.errors.order_multiple ?? entry.form.errors.lead_time_days ?? entry.form.errors.is_preferred ?? entry.form.errors.notes ?? entry.form.errors.status" /></form><p v-if="!products.length" class="text-[#637067]">No supplier products configured.</p></div>
        <form v-if="canUpdate" class="mt-8 grid gap-4 border border-dashed border-[#17211b]/30 bg-[#f8f5ed] p-6 md:grid-cols-3" @submit.prevent="addProduct"><h3 class="text-xl font-semibold md:col-span-3">Add supplier product</h3><label class="text-sm font-semibold md:col-span-2">Product variant<select v-model="productForm.product_variant_id" required class="mt-2 w-full border bg-white px-3 py-3 font-normal"><option value="" disabled>Select a variant</option><option v-for="variant in variants" :key="variant.id" :value="variant.id">{{ variant.product_name }} / {{ variant.sku }}<template v-if="variant.name"> / {{ variant.name }}</template></option></select></label><label class="text-sm font-semibold">Supplier SKU<input v-model="productForm.supplier_sku" class="mt-2 w-full border bg-white px-3 py-3 font-mono font-normal" /></label><label class="text-sm font-semibold">Unit cost<input v-model="productForm.unit_cost" required inputmode="decimal" class="mt-2 w-full border bg-white px-3 py-3 font-mono font-normal" /></label><label class="text-sm font-semibold">Currency<input v-model="productForm.currency" required maxlength="3" class="mt-2 w-full border bg-white px-3 py-3 font-mono font-normal uppercase" /></label><label class="text-sm font-semibold">Minimum order<input v-model.number="productForm.minimum_order_quantity" required type="number" min="1" class="mt-2 w-full border bg-white px-3 py-3 font-mono font-normal" /></label><label class="text-sm font-semibold">Order multiple<input v-model.number="productForm.order_multiple" type="number" min="1" class="mt-2 w-full border bg-white px-3 py-3 font-mono font-normal" /></label><label class="text-sm font-semibold">Lead time (days)<input v-model.number="productForm.lead_time_days" type="number" min="0" class="mt-2 w-full border bg-white px-3 py-3 font-mono font-normal" /></label><label class="flex items-center gap-2 pt-8 text-sm font-semibold"><input v-model="productForm.is_preferred" type="checkbox" /> Preferred</label><label class="text-sm font-semibold md:col-span-3">Notes<textarea v-model="productForm.notes" rows="2" maxlength="10000" class="mt-2 w-full border bg-white px-3 py-3 font-normal" /></label><div class="md:col-span-3"><FieldError :message="productForm.errors.product_variant_id ?? productForm.errors.unit_cost ?? productForm.errors.currency ?? productForm.errors.minimum_order_quantity ?? productForm.errors.order_multiple ?? productForm.errors.lead_time_days ?? productForm.errors.is_preferred ?? productForm.errors.notes" /><button :disabled="productForm.processing || !variants.length" class="mt-2 bg-[#17211b] px-5 py-3 text-sm font-semibold text-white disabled:opacity-50">Add product</button></div></form>
    </section></AdminLayout>
</template>
